/** [sql-lotFault.xml] LotFaultMapper.getComboLineList **/
SELECT LINE_CODE, '[' || LINE_CODE || '] ' || LINE_NM AS LINE_NM
FROM DNKR_LINE_CODE 
WHERE 1=1
AND COMPANY = #{st08Company}
AND FACTORY = #{st08Factory}

	AND VIEW_YN = #{viewYn}


	AND SMD_LINE = #{smdLine}


	AND MF_LINE =  #{mfLine}


	AND (MF_LINE =  #{mfLine} OR SMD_LINE = #{smdLine})

AND CLS_CODE ='E1'

/** [sql-lotFault.xml] LotFaultMapper.getComboEquipCodeList **/
SELECT CM07_CODE, CM07_NAME 
FROM TB_CM_07	
WHERE CM07_COMPANY = #{st08Company}
AND CM07_FACTORY = #{st08Factory}

	AND CM07_SMD = 'Y'

/** [sql-lotFault.xml] LotFaultMapper.getArrayList **/ SELECT CM05.CM05_VALUE AS VALUE, CM05.CM05_NAME AS NAME FROM TB_CM_04 CM04 ,TB_CM_05 CM05 WHERE 1=1 AND CM04.CM04_COMPANY = CM05.CM05_COMPANY AND CM04.CM04_FACTORY = CM05.CM05_FACTORY AND CM04.CM04_CODE = CM05.CM05_CODE AND CM04.CM04_CODE = 'PCB1' AND CM04.CM04_COMPANY = #{st08Company} AND CM04.CM04_FACTORY = #{st08Factory}
AND TO_NUMBER(CM05.CM05_VALUE) <= TO_NUMBER(#{arrayCnt})
ORDER BY TO_NUMBER(CM05.CM05_VALUE)

		/** [sql-lotFault.xml] LotFaultMapper.getSeq **/
		SELECT COALESCE(MAX(ST08_SEQ)+1,1) AS ST08_SEQ
          FROM TB_ST_08
          WHERE ST08_COMPANY = #{st08Company}
            AND ST08_FACTORY = #{st08Factory}
            AND TO_CHAR(ST08_DAT, 'YYYYMMDD') = TO_CHAR(SYSDATE, 'YYYYMMDD')

/** [sql-lotFault.xml] LotFaultMapper.getDuplicationLotFaultInfo **/
SELECT * 
FROM TB_ST_08
WHERE 1=1
AND ST08_COMPANY 	= #{st08Company}
AND ST08_FACTORY 	= #{st08Factory}
AND ST08_QRCODE 	= #{st08Qrcode}

mapper.insert:
    	/** [sql-lotFault.xml] LotFaultMapper.insertOfLotFault **/

			SELECT COALESCE(MAX(ST08_SEQ)+1,1) AS ST08_SEQ
			FROM TB_ST_08
			WHERE ST08_COMPANY = #{st08Company}
			AND ST08_FACTORY = #{st08Factory}
			AND TO_CHAR(ST08_DAT, 'YYYYMMDD') = TO_CHAR(SYSDATE, 'YYYYMMDD')


        INSERT INTO TB_ST_08
		(
			  ST08_COMPANY
			, ST08_FACTORY
			, ST08_NO
			, ST08_DAT
			, ST08_SEQ
			, ST08_GBN
			, ST08_PGBN
			, ST08_CODE
			, ST08_UNT
			, ST08_LOT
			, ST08_RMK
			, ST08_INDTE
			, ST08_EMPNO
			, ST08_QTY
			, ST08_LOT_SEQ
			, ST08_QRCODE
			, ST08_LINE
			, ST08_EQUIP_CODE
			, ST08_ARRAY
		)
		VALUES
		(
			  #{st08Company}
			, #{st08Factory}
			, CONCAT(TO_CHAR(SYSDATE, 'YYYYMMDD'), LPAD(#{st08Seq}, 5, '0'))
			, TO_DATE(TO_CHAR(SYSDATE, 'YYYY-MM-DD'), 'YYYY-MM-DD')
			, #{st08Seq}
			, #{st08Gbn}
			, #{st08Pgbn}
			, #{st08Code}
			, #{st08Unt}
			, #{st08Lot}
			, '[PDA]제조 공정 불량처리'
			, SYSDATE
			, #{st08Empno}
			, 1
			, #{st08LotSeq}
			, #{st08Qrcode}
			, #{st08Line}
			, #{st08EquipCode}
			, 1
		)
